package com.nigson.commerce.payment;
import java.util.*;
import java.time.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.*;
import com.nigson.commerce.order.*;
import com.nigson.commerce.inventory.StockLedger;
import com.nigson.commerce.cart.CartCheckout;
import com.nigson.commerce.platform.AuditWriter;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;

/** An elapsed reservation is not financial failure. UNKNOWN survives stock release and late monitoring. */
public final class PaymentExpiry {
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final OrderPolicy binding;private final PaymentPolicy policy;private final CheckoutPayments payments;private final OrderRepository orders;private final StockLedger stock;private final CartCheckout carts;private final AuditWriter audit;private final Clock clock;private final io.micrometer.core.instrument.MeterRegistry metrics;
 public PaymentExpiry(JdbcTemplate jdbc,PlatformTransactionManager manager,OrderPolicy binding,PaymentPolicy policy,CheckoutPayments payments,OrderRepository orders,StockLedger stock,CartCheckout carts,AuditWriter audit,Clock clock,io.micrometer.core.instrument.MeterRegistry metrics){this.jdbc=jdbc;tx=new TransactionTemplate(manager);tx.setTimeout(2);this.binding=binding;this.policy=policy;this.payments=payments;this.orders=orders;this.stock=stock;this.carts=carts;this.audit=audit;this.clock=clock;this.metrics=metrics;}
 public boolean expire(UUID order,UUID correlation){policy.require();ApiValues.uuid(order==null?null:order.toString());ApiValues.uuid(correlation==null?null:correlation.toString());if(!binding.enabled())throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("PROVIDER_CALL_INSIDE_TRANSACTION");if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT status='PENDING' AND reservation_expires_at<=? FROM commerce.sales_order WHERE id=?",Boolean.class,java.sql.Timestamp.from(clock.instant()),order)))return false;payments.inspect(order,correlation);
  return Boolean.TRUE.equals(tx.execute(s->{jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");var before=orders.find(order,true);var row=jdbc.queryForMap("SELECT reservation_expires_at,carrier_snapshot->>'mode' AS mode,cart_id FROM commerce.sales_order WHERE id=?",order);if(!before.status().equals("PENDING")||!Set.of("UNPAID","PENDING","FAILED").contains(before.paymentStatus())||row.get("reservation_expires_at")==null||((java.sql.Timestamp)row.get("reservation_expires_at")).toInstant().isAfter(clock.instant()))return false;binding.require(row.get("mode").toString());var attempts=jdbc.queryForList("SELECT * FROM commerce.payment_attempt WHERE order_id=? ORDER BY created_at DESC,id DESC LIMIT 1 FOR UPDATE",order);if(attempts.size()!=1)throw PaymentValues.rule();var a=attempts.getFirst();if(!a.get("provider").equals("PAYSTACK")||!a.get("merchant_account").equals(binding.merchantAccount())||!a.get("provider_mode").equals(binding.mode())||!a.get("currency_code").equals("NGN")||!before.currency().equals("NGN")||((java.math.BigDecimal)a.get("expected_amount")).compareTo(new java.math.BigDecimal(before.totals().grandTotal()))!=0)throw PaymentValues.rule();if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.payment_transaction t JOIN commerce.payment_attempt a ON a.id=t.attempt_id WHERE a.order_id=?)",Boolean.class,order))||a.get("state").equals("SUCCEEDED"))return false;
   if(Set.of("FAILED","CANCELLED").contains(a.get("state"))&&a.get("verified_at")!=null){var cancelled=orders.cancelled(order,before.version(),"payment-expiry","Independently verified unpaid reservation expiry",correlation);evidence(order,before.version(),correlation);return cancelled.status().equals("CANCELLED");}
   if(a.get("state").equals("INITIATING")&&a.get("initiating_until")!=null&&((java.sql.Timestamp)a.get("initiating_until")).toInstant().isAfter(clock.instant()))return false;
   if(!Set.of("INITIATING","PENDING","UNKNOWN").contains(a.get("state")))throw PaymentValues.rule();long version=((Number)a.get("version")).longValue();if(!a.get("state").equals("UNKNOWN")||a.get("next_reconcile_at")==null){if(version==Long.MAX_VALUE)throw PaymentValues.rule();jdbc.update("UPDATE commerce.payment_attempt SET state='UNKNOWN',initiating_until=NULL,next_reconcile_at=?,version=version+1,updated_at=?,updated_by='payment-expiry' WHERE id=?",java.sql.Timestamp.from(clock.instant().plusSeconds(30)),java.sql.Timestamp.from(clock.instant()),a.get("id"));audit.append("payment-expiry",AuditValues.ActorKind.SYSTEM,AuditValues.Action.PAYMENT_VERIFICATION,AuditValues.Resource.ORDER,order,correlation,AuditValues.Reason.RECONCILIATION,Map.of("state",a.get("state"),"version",version),Map.of("state","UNKNOWN","version",version+1,"providerMode",binding.mode()),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.payment.outcomes","state","UNKNOWN").increment();}});}
   if(((java.sql.Timestamp)row.get("reservation_expires_at")).toInstant().plusSeconds(policy.uncertainGraceSeconds()).isAfter(clock.instant()))return false;
   if(before.version()==Long.MAX_VALUE)throw PaymentValues.rule();jdbc.update("UPDATE commerce.sales_order SET status='CANCELLED',payment_status='PENDING',fulfillment_status='CANCELLED',version=version+1,updated_at=?,updated_by='payment-expiry' WHERE id=?",java.sql.Timestamp.from(clock.instant()),order);jdbc.update("INSERT INTO commerce.order_status_history(id,created_by,order_id,previous_status,new_status,reason) VALUES (?,'payment-expiry',?,'PENDING','CANCELLED','Configured uncertainty grace elapsed; payment monitoring retained')",EventCodec.uuid7(clock.instant()),order);stock.release(order,order,"payment-expiry",correlation);if(row.get("cart_id")!=null)carts.uncertainExpired(order,policy.uncertainGraceSeconds(),correlation);evidence(order,before.version(),correlation);return true;
  }));
 }
 private void evidence(UUID order,long version,UUID correlation){audit.append("payment-expiry",AuditValues.ActorKind.SYSTEM,AuditValues.Action.ORDER_CANCELLATION,AuditValues.Resource.ORDER,order,correlation,AuditValues.Reason.RECONCILIATION,Map.of("state","PENDING","version",version),Map.of("state","CANCELLED","version",version+1),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.order.commands","operation","CANCEL").increment();}});}
}
